    const gert::Shape* x_shape = context->GetInputShape(0);
    // Weight: (OC, C, KH, KW)
    const gert::Shape* w_shape = context->GetInputShape(1);

    uint32_t N = static_cast<uint32_t>(x_shape->GetDim(0));
    uint32_t C = static_cast<uint32_t>(x_shape->GetDim(1));
    uint32_t H = static_cast<uint32_t>(x_shape->GetDim(2));
    uint32_t W = static_cast<uint32_t>(x_shape->GetDim(3));

    uint32_t OC = static_cast<uint32_t>(w_shape->GetDim(0));
    uint32_t KH = static_cast<uint32_t>(w_shape->GetDim(2));
    uint32_t KW = static_cast<uint32_t>(w_shape->GetDim(3));

    // Fixed params for this standard conv (as in the original architecture)
    uint32_t strideH = 4;
    uint32_t strideW = 4;
    uint32_t padH = 2;
    uint32_t padW = 2;

    uint32_t OH = static_cast<uint32_t>((static_cast<int64_t>(H) + 2 * padH - KH) / strideH + 1);
    uint32_t OW = static_cast<uint32_t>((static_cast<int64_t>(W) + 2 * padW - KW) / strideW + 1);

    tiling.set_N(N);
    tiling.set_C(C);
    tiling.set_H(H);
    tiling.set_W(W);
    tiling.set_OC(OC);
    tiling.set_KH(KH);
    tiling.set_KW(KW);
    tiling.set_strideH(strideH);
    tiling.set_strideW(strideW);
    tiling.set_padH(padH);
    tiling.set_padW(padW);
    tiling.set_OH(OH);
    tiling.set_OW(OW);

    // Set reasonable block dim using platform info
    auto ascendcPlatform = platform_ascendc::PlatformAscendC(context->GetPlatformInfo());
    auto aicNum = ascendcPlatform.GetCoreNumAic();
    auto aivNum = ascendcPlatform.GetCoreNumAiv();
    uint32_t sliceNum = aivNum == 0 ? 20 : aivNum; // fallback
    context->SetBlockDim(ascendcPlatform.CalcTschBlockDim(sliceNum, aicNum, aivNum));

    tiling.SaveToBuffer(context->GetRawTilingData()->GetData(), context->GetRawTilingData()->GetCapacity());
    context->GetRawTilingData()->SetDataSize(tiling.GetDataSize());

    size_t *currentWorkspace = context->GetWorkspaceSizes(1);
    currentWorkspace[0] = 0;
    return ge::GRAPH_SUCCESS;
}
